using UnityEngine;
using UnityEngine.UI;

namespace LightShadow.UI
{
    // Runtime access to the horror glass UI kit (T_UI_Glass_*, generated by UiThemeTool).
    // The sprites ship as Resources copies so panels that are built at runtime, or that
    // were baked into a scene before the kit existed, can still use the same look.
    public static class GlassSkin
    {
        static Sprite panel;
        static Sprite button;

        public static Sprite Panel
        {
            get { if (panel == null) panel = Resources.Load<Sprite>("UI/T_UI_Glass_Panel"); return panel; }
        }

        public static Sprite Button
        {
            get { if (button == null) button = Resources.Load<Sprite>("UI/T_UI_Glass_Button"); return button; }
        }

        // Puts the glass card on an Image. The card's own alpha carries the body, so the
        // tint stays white and only the opacity is chosen by the caller. Returns false
        // (image untouched) when the sprite is missing.
        public static bool ApplyPanel(Image image, float alpha = 0.97f)
        {
            return Apply(image, Panel, alpha);
        }

        public static bool ApplyButton(Image image, float alpha = 1f)
        {
            return Apply(image, Button, alpha);
        }

        static bool Apply(Image image, Sprite sprite, float alpha)
        {
            if (image == null || sprite == null) return false;
            image.sprite = sprite;
            image.type = Image.Type.Sliced;
            image.color = new Color(1f, 1f, 1f, Mathf.Clamp01(alpha));
            return true;
        }
    }
}
